using System.Text;
using System.Reflection;
using UnityEngine;
using UnityEngine.UI;

public static class PlayState
{
    public static string Run()
    {
        var sb = new StringBuilder();
        sb.AppendLine("isPlaying=" + UnityEditor.EditorApplication.isPlaying);
        var canvas = GameObject.Find("MainMenuCanvas");
        if (canvas == null) { sb.AppendLine("NO CANVAS"); return sb.ToString(); }
        var cg = canvas.GetComponent<CanvasGroup>();
        sb.AppendLine("canvas alpha=" + (cg ? cg.alpha.ToString() : "none") + " interactable=" + (cg ? cg.interactable.ToString() : "-"));
        var title = canvas.transform.Find("TitleComposition");
        if (title) { var g = title.GetComponent<CanvasGroup>(); sb.AppendLine("title alpha=" + (g ? g.alpha.ToString() : "none")); }
        foreach (var n in new[] { "BtnPLAY", "BtnSETTINGS", "BtnCREDITS", "BtnQUIT" })
        {
            var b = canvas.transform.Find(n);
            if (b) { var g = b.GetComponent<CanvasGroup>(); var r = (RectTransform)b; sb.AppendLine(n + " alpha=" + (g ? g.alpha.ToString() : "none") + " pos=" + r.anchoredPosition); }
        }
        var menu = canvas.GetComponent<MainMenuUI>();
        if (menu != null)
        {
            var flags = BindingFlags.Instance | BindingFlags.NonPublic;
            sb.AppendLine("entering=" + menu.GetType().GetField("entering", flags).GetValue(menu));
            sb.AppendLine("transitioning=" + menu.GetType().GetField("transitioning", flags).GetValue(menu));
            sb.AppendLine("menuButtons=" + (menu.menuButtons == null ? "null" : menu.menuButtons.Length.ToString()));
            sb.AppendLine("menuMotion=" + (menu.menuMotion ? "ok" : "NULL") + " transition=" + (menu.transition ? "ok" : "NULL"));
            sb.AppendLine("activePanel=" + (menu.GetType().GetField("activePanel", flags).GetValue(menu) ?? "null"));
        }
        else sb.AppendLine("MainMenuUI MISSING");
        var es = UnityEngine.EventSystems.EventSystem.current;
        sb.AppendLine("EventSystem=" + (es ? es.gameObject.name + " currentSelected=" + (es.currentSelectedGameObject ? es.currentSelectedGameObject.name : "none") : "null"));
        foreach (var e in UnityEngine.Resources.FindObjectsOfTypeAll<UnityEngine.UI.Text>())
            if (e && e.transform.IsChildOf(canvas.transform)) { }
        return sb.ToString();
    }
}
